"use client";

import { useEffect, useState } from "react";
import type { components } from "@/lib/api-schema";
import { Calculated, Findings, References, minutes } from "./evidence-views";

type Analysis = components["schemas"]["AnalysisOut"];
type Tab = "overview" | "encounters" | "evidence";
const domains = [
  ["symptoms", "Symptoms and clinical course"],
  ["function", "Functioning"],
  ["treatment", "Treatment"],
  ["measurement", "Measurements"],
  ["plan", "Treatment plan"],
  ["other", "Other findings"],
] as const;

export function AbstractionView({
  run,
  onSource,
}: {
  run: Analysis;
  onSource: (revision: string, span: string) => void;
}) {
  const [tab, setTab] = useState<Tab>("overview");
  const [reviewTarget, setReviewTarget] = useState("");
  useEffect(() => {
    if (tab !== "encounters" || !reviewTarget) return;
    const item = document.getElementById(
      `encounter-${encodeURIComponent(reviewTarget)}`,
    );
    item?.setAttribute("open", "");
    item?.scrollIntoView({ block: "center" });
  }, [tab, reviewTarget]);
  const draft = run.result?.abstraction;
  if (!draft) return null;
  const citations = run.result?.citations ?? [];
  const calculations = run.result?.calculations;
  const concerns = draft.encounters.filter(
    (event) =>
      event.disposition === "uncertain" ||
      (event.disposition === "included" && event.alternatives.length !== 1),
  );
  const unusable = draft.coverage.filter((item) => item.status === "unusable");
  const tabs = [
    ["overview", "Overview"],
    ["encounters", `Encounters (${draft.encounters.length})`],
    ["evidence", "Sources & structured data"],
  ] as const;
  return (
    <>
      <div
        className="abstraction-tabs"
        role="tablist"
        aria-label="Abstraction views"
      >
        {tabs.map(([id, label]) => (
          <button
            key={id}
            role="tab"
            id={`abstraction-tab-${id}`}
            aria-selected={tab === id}
            aria-controls={`abstraction-panel-${id}`}
            onClick={() => setTab(id)}
          >
            {label}
          </button>
        ))}
      </div>
      <div
        role="tabpanel"
        id={`abstraction-panel-${tab}`}
        aria-labelledby={`abstraction-tab-${tab}`}
      >
        {tab === "overview" && (
          <>
            <div className="abstraction-overview-stats">
              <div>
                <strong>
                  {draft.coverage.length - unusable.length}/
                  {draft.coverage.length}
                </strong>
                <span>sources represented</span>
              </div>
              <div>
                <strong>{draft.encounters.length}</strong>
                <span>documented encounters</span>
              </div>
              <div>
                <strong>{concerns.length + unusable.length}</strong>
                <span>unresolved event / source issues</span>
              </div>
            </div>
            {(concerns.length > 0 || unusable.length > 0) && (
              <section className="abstraction-review">
                <h3>Needs review</h3>
                {concerns.map((event) => {
                  const contribution = calculations?.contributions.find(
                    (row) => row.encounter_id === event.encounter_id,
                  );
                  return (
                    <div key={event.encounter_id} className="review-item">
                      <div>
                        <strong>
                          {event.date} · {event.modality}
                        </strong>
                        <p>
                          {event.disposition === "uncertain"
                            ? "Attendance or eligibility is unresolved."
                            : event.alternatives.length > 1
                              ? `Competing source accounts: ${contribution && contribution.seconds.length > 1 ? minutes(contribution.seconds) : "different accounts of patient contact"}.`
                              : "Patient-contact duration is unknown."}
                        </p>
                      </div>
                      <button
                        className="secondary"
                        onClick={() => {
                          setReviewTarget(event.encounter_id);
                          setTab("encounters");
                        }}
                      >
                        Inspect accounts →
                      </button>
                    </div>
                  );
                })}
                {unusable.map((item) => (
                  <p key={item.revision_id}>Source gap: {item.note}</p>
                ))}
              </section>
            )}
            <h3 className="clinical-section-title">Clinical overview</h3>
            <p className="muted-text">
              Extracted findings grouped by clinical topic. Expand a topic or
              source to inspect the supporting record.
            </p>
            <div className="clinical-topics">
              {domains.map(([category, label]) => {
                const findings = draft.findings.filter(
                  (claim) => claim.category === category,
                );
                if (!findings.length) return null;
                return (
                  <details
                    className="clinical-topic"
                    key={category}
                    open={category === "symptoms" || category === "function"}
                  >
                    <summary>
                      {label}
                      <span className="count">{findings.length}</span>
                    </summary>
                    {findings.map((claim, index) => (
                      <article key={index}>
                        <p>{claim.text}</p>
                        <details className="finding-sources">
                          <summary>Supporting sources</summary>
                          <References
                            ids={claim.citations}
                            citations={citations}
                            onSource={onSource}
                          />
                        </details>
                      </article>
                    ))}
                  </details>
                );
              })}
            </div>
            {draft.limitations.length > 0 && (
              <details className="coverage-details">
                <summary>
                  Additional uncertainty and limitations (
                  {draft.limitations.length})
                </summary>
                {draft.limitations.map((limitation, index) => (
                  <p key={index}>{limitation}</p>
                ))}
              </details>
            )}
          </>
        )}
        {tab === "encounters" && (
          <>
            <h3 className="clinical-section-title">Encounter ledger</h3>
            <p className="muted-text">
              One row per encounter. Included and excluded contacts stay
              visible; expand a row for time intervals and competing source
              accounts.
            </p>
            <div className="encounter-list">
              {[...draft.encounters]
                .sort(
                  (a, b) =>
                    a.date.localeCompare(b.date) ||
                    a.encounter_id.localeCompare(b.encounter_id),
                )
                .map((event) => (
                  <details
                    className="encounter"
                    id={`encounter-${encodeURIComponent(event.encounter_id)}`}
                    key={event.encounter_id}
                  >
                    <summary>
                      <span>
                        <strong>{event.date}</strong>
                        <small>
                          {event.encounter_id} · {event.modality}
                        </small>
                      </span>
                      <span className={`disposition ${event.disposition}`}>
                        {event.disposition}
                      </span>
                      <strong>
                        {event.disposition === "excluded"
                          ? "—"
                          : minutes(
                              run.result?.calculations?.contributions.find(
                                (row) =>
                                  row.encounter_id === event.encounter_id,
                              )?.seconds ?? [],
                            )}
                      </strong>
                    </summary>
                    <p>{event.explanation}</p>
                    <References
                      ids={event.citations}
                      citations={citations}
                      onSource={onSource}
                    />
                    <h4>Source accounts</h4>
                    <Findings
                      claims={event.source_accounts}
                      citations={citations}
                      onSource={onSource}
                    />
                    {event.alternatives.map((account, index) => (
                      <div className="duration-account" key={index}>
                        <strong>
                          {event.alternatives.length > 1
                            ? `Alternative ${index + 1}`
                            : "Time basis"}
                        </strong>
                        <p>{account.basis}</p>
                        {account.stated_minutes !== null ? (
                          <p>
                            Explicit patient contact: {account.stated_minutes}{" "}
                            min
                          </p>
                        ) : (
                          <>
                            <p>
                              Contact:{" "}
                              {account.contact
                                .map((v) => `${v.start}–${v.end}`)
                                .join(", ")}
                            </p>
                            <p>
                              Patient present:{" "}
                              {account.patient_presence
                                .map((v) => `${v.start}–${v.end}`)
                                .join(", ")}
                            </p>
                            <p>
                              Breaks:{" "}
                              {account.breaks
                                .map((v) => `${v.start}–${v.end}`)
                                .join(", ") || "None documented"}
                            </p>
                          </>
                        )}
                        <References
                          ids={account.citations}
                          citations={citations}
                          onSource={onSource}
                        />
                      </div>
                    ))}
                  </details>
                ))}
            </div>

            {calculations && (
              <details className="coverage-details">
                <summary>
                  Treatment totals, weekly goals, and calculation details
                </summary>
                <Calculated
                  value={calculations}
                  citations={citations}
                  onSource={onSource}
                />
              </details>
            )}
          </>
        )}
        {tab === "evidence" && (
          <>
            <h3 className="clinical-section-title">Source coverage</h3>
            <p className="muted-text">
              Coverage refers to this source snapshot. It does not establish
              that the full clinical record is complete.
            </p>
            {draft.coverage.map((item, index) => (
              <article className="coverage-record" key={item.revision_id}>
                <button onClick={() => onSource(item.revision_id, "")}>
                  {citations.find(
                    (citation) => citation.revision_id === item.revision_id,
                  )?.filename ?? `Source ${index + 1}`}{" "}
                  ↗
                </button>
                <span>
                  {item.status === "reviewed"
                    ? "Represented in draft"
                    : "Needs review"}
                </span>
                <p>{item.note}</p>
              </article>
            ))}
            <details className="coverage-details">
              <summary>Inspect structured abstraction JSON</summary>
              <p>
                Machine-readable draft: encounters, duration alternatives,
                findings, plan rules, and source references. Clinical findings
                are currently text claims, not a fully normalized clinical
                record.
              </p>
              <pre className="abstraction-json">
                {JSON.stringify(draft, null, 2)}
              </pre>
            </details>
          </>
        )}
      </div>
    </>
  );
}
